def f(n):
    if n == 0:
        return []
    result = []
    factorial = 1
    sum_ = 0
    for i in range(1, n + 1):
        sum_ += i
        if i % 2 == 0:
            factorial *= i
            result.append(factorial)
        else:
            result.append(sum_)
    return result
